<?php
namespace App\Http\Requests\Admin;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;
class ProductRequest extends FormRequest {public function authorize(){return $this->user()?->isAdmin()??false;}public function rules(){return ['name'=>['required','string','max:191'],'slug'=>['required','alpha_dash','max:191',Rule::unique('products','slug')->ignore($this->route('product'))],'sku'=>['required','max:100',Rule::unique('products','sku')->ignore($this->route('product'))],'category_id'=>'required|exists:categories,id','subcategory_id'=>'nullable|exists:categories,id','short_description'=>'nullable|string|max:500','description'=>'nullable|string','material'=>'nullable|string|max:191','price'=>'required|numeric|min:0','compare_price'=>'nullable|numeric|gte:price','cost_price'=>'nullable|numeric|min:0','stock'=>'required|integer|min:0','low_stock_threshold'=>'required|integer|min:0','weight'=>'nullable|numeric|min:0','colors'=>'nullable|string','sizes'=>'nullable|string','tags'=>'nullable|string','images'=>'nullable|array|max:6','images.*'=>'image|mimes:jpg,jpeg,png,webp|max:4096','image_alt'=>'nullable|array|max:6','is_active'=>'nullable|boolean','is_featured'=>'nullable|boolean','is_new'=>'nullable|boolean','is_bestseller'=>'nullable|boolean','is_limited'=>'nullable|boolean','meta_title'=>'nullable|string|max:70','meta_description'=>'nullable|string|max:170','canonical_url'=>'nullable|url|max:255'];}}
